class BankAccount:
    def __init__(self, owner, balance=0):
        if balance < 0:
            raise ValueError("opening balance cannot be negative")
        self.owner = owner
        self._balance = balance
        self._history = []

    @property
    def balance(self):
        return self._balance

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError("deposit must be positive")
        self._balance += amount
        self._history.append(("deposit", amount))

    def withdraw(self, amount):
        if amount <= 0:
            raise ValueError("withdrawal must be positive")
        if amount > self._balance:
            raise ValueError("insufficient funds")
        self._balance -= amount
        self._history.append(("withdraw", amount))

    def transfer(self, other, amount):
        self.withdraw(amount)
        other.deposit(amount)

    def history(self):
        return list(self._history)

unitTests:
@test("deposits and withdrawals")
def _():
    a = BankAccount("Ada", 100)
    a.deposit(50)
    a.withdraw(30)
    check_eq(a.balance, 120)
    check_eq(a.history(), [("deposit", 50), ("withdraw", 30)])

@test("invalid operations change nothing")
def _():
    a = BankAccount("Ada", 10)
    check_raises(ValueError, a.withdraw, 20)
    check_raises(ValueError, a.deposit, 0)
    check_raises(ValueError, a.withdraw, -5)
    check_raises(ValueError, BankAccount, "Bad", -1)
    check_eq(a.balance, 10)
    check_eq(a.history(), [])

@test("the balance is read-only")
def _():
    a = BankAccount("Ada", 10)
    try:
        a.balance = 1000
        check(False, "setting balance should fail")
    except AttributeError:
        pass
    check_eq(a.balance, 10)

@test("transfers")
def _():
    a, b = BankAccount("Ada", 100), BankAccount("Grace")
    a.transfer(b, 40)
    check_eq((a.balance, b.balance), (60, 40))
    check_raises(ValueError, a.transfer, b, 1000)
    check_eq((a.balance, b.balance), (60, 40))
    check_eq(b.history(), [("deposit", 40)])

@test("history is a copy")
def _():
    a = BankAccount("Ada")
    a.deposit(5)
    a.history().clear()
    check_eq(len(a.history()), 1)

